// Overclock service worker: precaches the whole game so it runs offline and installs as an app.
// Scope is the folder that holds this file ('/' locally, '/overclock/' on GitHub Pages).
// The block between the BUILD markers is generated by tools/build_sw.py: do not edit it by hand.

// BUILD:START
const VERSION = '10b964c7e848';
const PRECACHE = [
  './',
  './icons/apple-touch-icon.png',
  './icons/favicon-32.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './js/api.js',
  './js/boot.js',
  './js/engine.js',
  './js/font.js',
  './js/history.js',
  './js/i18n.js',
  './js/isa.js',
  './js/main.js',
  './js/menu.js',
  './js/modes.js',
  './js/pixel.js',
  './js/proc-gpu.js',
  './js/proc-mcu.js',
  './js/proc-multiciclo.js',
  './js/proc-pipeline.js',
  './js/proc-singolo.js',
  './js/procs.js',
  './js/pwa.js',
  './js/qr.js',
  './js/route.js',
  './js/scene.js',
  './js/sfx.js',
  './js/sha256.js',
  './manifest.webmanifest',
  './vendor/fonts/ibm-plex-mono-400-latin-ext.woff2',
  './vendor/fonts/ibm-plex-mono-400-latin.woff2',
  './vendor/fonts/ibm-plex-mono-600-latin-ext.woff2',
  './vendor/fonts/ibm-plex-mono-600-latin.woff2',
  './vendor/fonts/ibm-plex-mono-700-latin-ext.woff2',
  './vendor/fonts/ibm-plex-mono-700-latin.woff2',
  './vendor/fonts/plex-mono.css',
  './vendor/three/build/three.module.js',
  './vendor/three/examples/jsm/postprocessing/Pass.js',
  './vendor/three/examples/jsm/postprocessing/UnrealBloomPass.js',
  './vendor/three/examples/jsm/shaders/CopyShader.js',
  './vendor/three/examples/jsm/shaders/LuminosityHighPassShader.js',
];
// BUILD:END

const CACHE = `overclock-${VERSION}`;
const abs = u => new URL(u, self.location).href;
const INDEX = abs('./');
const APP_PAGES = new Set([INDEX, abs('./index.html')]);
const PRECACHED = new Set(PRECACHE.map(abs));

// install: download every file of this version ('reload' skips the browser's HTTP cache), then take over
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE)
      .then(cache => cache.addAll(PRECACHE.map(u => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

// activate: drop the caches of older versions, then control the open pages right away
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('overclock-') && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

const fromCache = (url, network) =>
  caches.open(CACHE)
    .then(cache => cache.match(url, { ignoreSearch: true }))
    .then(hit => hit || fetch(network));

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;                                  // POSTs etc.: straight to the network
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;                   // other sites: not ours
  if (url.pathname.includes('/api/')) return;                        // the server's API: never cached
  const page = url.origin + url.pathname;                            // without ?query and #hash
  if (req.mode === 'navigate') {
    // the game's page (also with ?sfida=ABCDE etc.): the cached index, else the network
    if (APP_PAGES.has(page)) event.respondWith(fromCache(INDEX, req));
    return;                                                          // other pages: network
  }
  if (PRECACHED.has(page)) event.respondWith(fromCache(req, req));  // game files: cache first
  // everything else: network (default)
});
